// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProjectWorkload) predicate.ProjectWorkload {
	return predicate.ProjectWorkload(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProjectWorkload) predicate.ProjectWorkload {
	return predicate.ProjectWorkload(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProjectWorkload) predicate.ProjectWorkload {
	return predicate.ProjectWorkload(sql.NotPredicates(p))
}
